s=A.dm("<!doctype html>\n<html lang=\"fr\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>__TITLE__</title>\n<link rel=\"stylesheet\" href=\"__LEAFLET_CSS__\">\n<style>\n  :root { --bg:#0f1220; --surface:#1a1f33; --border:#2a3150; --text:#e8ebf5;\n          --muted:#9aa3bf; --accent:#2f80ed; }\n  * { box-sizing: border-box; }\n  html, body { margin:0; height:100%; background:var(--bg); color:var(--text);\n    font:15px/1.45 system-ui,-apple-system,\"Segoe UI\",Roboto,sans-serif; }\n  header { padding:12px 16px; border-bottom:1px solid var(--border); }\n  header h1 { margin:0; font-size:1.15rem; }\n  header p { margin:2px 0 0; color:var(--muted); font-size:.85rem; }\n  .layout { display:grid; grid-template-columns:1fr; }\n  #map { height:60vh; min-height:320px; }\n  #list { padding:12px 16px 32px; }\n  @media (min-width: 900px) {\n    .layout { grid-template-columns:1fr 380px; height:calc(100vh - 62px); }\n    #map { height:100%; }\n    #list { overflow-y:auto; border-left:1px solid var(--border); }\n  }\n  .grid { display:grid; grid-template-columns:repeat(auto-fill,minmax(150px,1fr)); gap:10px; }\n  .card { background:var(--surface); border:1px solid var(--border); border-radius:12px;\n    overflow:hidden; cursor:pointer; text-align:left; color:inherit; padding:0; font:inherit; }\n  .card:hover, .card:focus-visible { border-color:var(--accent); outline:none; }\n  .card img, .card .noimg { display:block; width:100%; aspect-ratio:4/3; object-fit:cover; background:#000; }\n  .card .noimg { display:flex; align-items:center; justify-content:center; color:var(--muted); }\n  .card .info { padding:6px 8px; font-size:.8rem; }\n  .card .num { font-weight:700; color:var(--accent); margin-right:4px; }\n  .card .nogps { color:#f2994a; }\n  .pin { width:28px; height:28px; border-radius:50% 50% 50% 0; transform:rotate(-45deg);\n    background:var(--accent); border:2px solid #fff; box-shadow:0 2px 6px rgba(0,0,0,.5);\n    display:flex; align-items:center; justify-content:center; }\n  .pin span { transform:rotate(45deg); color:#fff; font:700 12px system-ui,sans-serif; }\n  .leaflet-popup-content { margin:10px; width:240px; }\n  .pop img { width:100%; border-radius:8px; cursor:zoom-in; display:block; }\n  .pop b { display:block; margin:6px 0 2px; word-break:break-all; }\n  .pop div { font-size:12px; color:#333; }\n  .pop .xy { font-family:ui-monospace,Consolas,monospace; color:#0b5394; }\n  #viewer { position:fixed; inset:0; background:rgba(0,0,0,.92); display:none;\n    flex-direction:column; align-items:center; justify-content:center; z-index:2000; padding:12px; }\n  #viewer.open { display:flex; }\n  #viewer img { max-width:100%; max-height:calc(100vh - 110px); object-fit:contain; }\n  #viewer .cap { margin-top:10px; text-align:center; font-size:.9rem; }\n  #viewer button { position:absolute; background:rgba(255,255,255,.12); color:#fff; border:0;\n    width:44px; height:44px; border-radius:50%; font-size:22px; cursor:pointer; }\n  #viewer .close { top:12px; right:12px; }\n  #viewer .prev { left:12px; top:50%; }\n  #viewer .next { right:12px; top:50%; }\n  header { display:flex; align-items:center; gap:12px; }\n  header .titles { flex:1; min-width:0; }\n  .btn { background:var(--accent); color:#fff; border:0; border-radius:10px;\n    padding:9px 14px; font:600 .9rem system-ui,sans-serif; cursor:pointer; white-space:nowrap; }\n  .btn.ghost { background:transparent; color:var(--text); border:1px solid var(--border); }\n  .btn:disabled { opacity:.5; cursor:default; }\n  #pdfdlg { position:fixed; inset:0; background:rgba(0,0,0,.7); display:none;\n    align-items:center; justify-content:center; z-index:2100; padding:16px; }\n  #pdfdlg.open { display:flex; }\n  #pdfdlg .box { background:var(--surface); border:1px solid var(--border); border-radius:14px;\n    padding:18px; width:100%; max-width:360px; }\n  #pdfdlg h2 { margin:0 0 12px; font-size:1.1rem; }\n  #pdfdlg fieldset { border:0; margin:0 0 12px; padding:0; }\n  #pdfdlg .field { display:block; color:var(--muted); font-size:.85rem; margin:0 0 6px; }\n  #pdfname { width:100%; margin:0 0 14px; padding:9px 10px; border-radius:8px;\n    border:1px solid var(--border); background:var(--bg); color:var(--text); font:inherit; }\n  #pdfdlg legend { color:var(--muted); font-size:.85rem; margin-bottom:6px; }\n  #pdfdlg label { display:inline-flex; align-items:center; gap:6px; margin-right:16px; cursor:pointer; }\n  #pdfdlg .msg { color:var(--muted); font-size:.85rem; min-height:1.2em; margin:4px 0 12px; }\n  #pdfdlg .actions { display:flex; gap:8px; justify-content:flex-end; flex-wrap:wrap; }\n  /* Mise en page d'impression : hors ecran (Leaflet a besoin d'une taille\n     reelle pour charger les tuiles), seule visible a l'impression */\n  #print { position:absolute; left:-20000px; top:0; background:#fff; color:#000; }\n  .ppage { display:flex; flex-direction:column; overflow:hidden; background:#fff;\n    break-after:page; page-break-after:always; font:10pt system-ui,sans-serif; }\n  .ppage:last-child { break-after:auto; page-break-after:auto; }\n  .ptitle { margin:0 0 2mm; font-size:14pt; }\n  .psub { margin:0 0 3mm; color:#444; font-size:9pt; }\n  .pmap { flex:none; border:1px solid #999; }\n  .pgrid { flex:1; display:grid; gap:4mm; min-height:0; }\n  .pcell { display:flex; flex-direction:column; min-height:0; border:1px solid #bbb; padding:2mm; }\n  .pcell img { flex:1; min-height:0; width:100%; object-fit:contain; }\n  .pcell .noimg { flex:1; display:flex; align-items:center; justify-content:center; color:#888; }\n  .pcap { margin-top:1.5mm; font-size:8.5pt; line-height:1.3; }\n  .pcap b { word-break:break-all; }\n  .pcap .xy { font-family:ui-monospace,Consolas,monospace; color:#0b5394; }\n  @media print {\n    html, body { background:#fff !important; height:auto; }\n    body > *:not(#print) { display:none !important; }\n    #print { position:static; left:auto; }\n    * { -webkit-print-color-adjust:exact; print-color-adjust:exact; }\n  }\n</style>\n</head>\n<body>\n<header>\n  <div class=\"titles\"><h1 id=\"title\"></h1><p id=\"sub\"></p></div>\n  <button class=\"btn\" id=\"pdfbtn\" type=\"button\">Exporter en PDF</button>\n</header>\n<div class=\"layout\">\n  <div id=\"map\"></div>\n  <section id=\"list\"><div class=\"grid\" id=\"grid\"></div></section>\n</div>\n<div id=\"viewer\" role=\"dialog\" aria-modal=\"true\">\n  <button class=\"close\" aria-label=\"Fermer\">&times;</button>\n  <button class=\"prev\" aria-label=\"Photo pr\xe9c\xe9dente\">&#8249;</button>\n  <img alt=\"\">\n  <div class=\"cap\"></div>\n  <button class=\"next\" aria-label=\"Photo suivante\">&#8250;</button>\n</div>\n<div id=\"pdfdlg\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"pdftitle\">\n  <div class=\"box\">\n    <h2 id=\"pdftitle\">Exporter en PDF</h2>\n    <label class=\"field\" for=\"pdfname\">Titre de la carte</label>\n    <input id=\"pdfname\" type=\"text\" maxlength=\"120\" autocomplete=\"off\">\n    <fieldset><legend>Format</legend>\n      <label><input type=\"radio\" name=\"fmt\" value=\"A4\" checked> A4</label>\n      <label><input type=\"radio\" name=\"fmt\" value=\"A3\"> A3</label>\n    </fieldset>\n    <fieldset><legend>Orientation</legend>\n      <label><input type=\"radio\" name=\"ori\" value=\"landscape\" checked> Paysage</label>\n      <label><input type=\"radio\" name=\"ori\" value=\"portrait\"> Portrait</label>\n    </fieldset>\n    <div class=\"msg\" id=\"pdfmsg\">Page 1 : la carte (vue actuelle). Pages suivantes : 6 photos par page.</div>\n    <div class=\"actions\">\n      <button class=\"btn ghost\" id=\"pdfcancel\" type=\"button\">Annuler</button>\n      <button class=\"btn\" id=\"pdfprep\" type=\"button\">Pr\xe9parer</button>\n      <button class=\"btn\" id=\"pdfgo\" type=\"button\" hidden>Imprimer / Enregistrer en PDF</button>\n    </div>\n  </div>\n</div>\n<script type=\"application/json\" id=\"data\">__DATA__</script>\n<script src=\"__LEAFLET_JS__\"></script>\n<script>\n(function () {\n  var data = JSON.parse(document.getElementById('data').textContent);\n  var photos = data.photos;\n  var located = photos.filter(function (p) { return p.lat !== null; });\n  document.getElementById('title').textContent = data.title;\n  document.getElementById('sub').textContent = photos.length + ' photo(s), ' +\n    located.length + ' g\xe9olocalis\xe9e(s) \xb7 Lambert 93 (EPSG:2154) \xb7 ' + data.generated;\n\n  function el(tag, cls, text) {\n    var e = document.createElement(tag);\n    if (cls) e.className = cls;\n    if (text !== undefined && text !== null) e.textContent = text;\n    return e;\n  }\n  function fmt(v) { return v.toLocaleString('fr-FR', {minimumFractionDigits: 2, maximumFractionDigits: 2}); }\n  function details(p) {\n    var lines = [p.date + ' ' + p.time];\n    if (p.x !== null) lines.push('X ' + fmt(p.x) + ' \xb7 Y ' + fmt(p.y));\n    else lines.push('Sans position GPS');\n    if (p.address) lines.push(p.address);\n    var extra = [];\n    if (p.alt !== null) extra.push('Alt. ' + p.alt + ' m');\n    if (p.acc !== null) extra.push('Pr\xe9cision \xb1 ' + p.acc + ' m');\n    if (extra.length) lines.push(extra.join(' \xb7 '));\n    return lines;\n  }\n\n  // Visionneuse plein ecran\n  var viewer = document.getElementById('viewer');\n  var vImg = viewer.querySelector('img');\n  var vCap = viewer.querySelector('.cap');\n  var current = 0;\n  var withImg = photos.map(function (p, i) { return i; }).filter(function (i) { return photos[i].img; });\n  function show(i) {\n    current = i;\n    var p = photos[i];\n    vImg.src = p.img;\n    vCap.textContent = '';\n    vCap.appendChild(el('b', null, (i + 1) + '. ' + p.name));\n    details(p).forEach(function (l) { vCap.appendChild(el('div', null, l)); });\n    viewer.classList.add('open');\n  }\n  function step(d) {\n    var k = withImg.indexOf(current);\n    if (k < 0) return;\n    show(withImg[(k + d + withImg.length) % withImg.length]);\n  }\n  viewer.querySelector('.close').onclick = function () { viewer.classList.remove('open'); };\n  viewer.querySelector('.prev').onclick = function () { step(-1); };\n  viewer.querySelector('.next').onclick = function () { step(1); };\n  viewer.addEventListener('click', function (e) { if (e.target === viewer) viewer.classList.remove('open'); });\n  document.addEventListener('keydown', function (e) {\n    if (!viewer.classList.contains('open')) return;\n    if (e.key === 'Escape') viewer.classList.remove('open');\n    if (e.key === 'ArrowLeft') step(-1);\n    if (e.key === 'ArrowRight') step(1);\n  });\n\n  // Carte\n  var map = null;\n  var markers = {};\n  var activeLayer = data.layers[0];\n  function pinIcon(i) {\n    return L.divIcon({className: '', iconSize: [28, 28], iconAnchor: [14, 28],\n      popupAnchor: [0, -26], html: '<div class=\"pin\"><span>' + (i + 1) + '</span></div>'});\n  }\n  if (window.L) {\n    map = L.map('map');\n    var layers = {};\n    data.layers.forEach(function (l, k) {\n      var t = L.tileLayer(l.url, {subdomains: l.subdomains, maxZoom: 19,\n        maxNativeZoom: l.maxZoom, attribution: l.attribution});\n      if (k === 0) t.addTo(map);\n      t._def = l;\n      layers[l.name] = t;\n    });\n    map.on('baselayerchange', function (e) { activeLayer = e.layer._def; });\n    L.control.layers(layers, null, {collapsed: false}).addTo(map);\n    L.control.scale({imperial: false}).addTo(map);\n\n    photos.forEach(function (p, i) {\n      if (p.lat === null) return;\n      var icon = pinIcon(i);\n      var pop = el('div', 'pop');\n      if (p.img) {\n        var im = el('img');\n        im.src = p.img;\n        im.alt = p.name;\n        im.onclick = function () { show(i); };\n        pop.appendChild(im);\n      }\n      pop.appendChild(el('b', null, (i + 1) + '. ' + p.name));\n      details(p).forEach(function (l, k) { pop.appendChild(el('div', k === 1 ? 'xy' : null, l)); });\n      markers[i] = L.marker([p.lat, p.lng], {icon: icon}).bindPopup(pop).addTo(map);\n    });\n    if (located.length) {\n      map.fitBounds(L.latLngBounds(located.map(function (p) { return [p.lat, p.lng]; })),\n        {padding: [40, 40], maxZoom: 18});\n    } else {\n      map.setView([46.6, 2.5], 5);\n    }\n  } else {\n    document.getElementById('map').textContent =\n      'Carte indisponible : connexion internet n\xe9cessaire pour afficher le fond de carte.';\n  }\n\n  // Export PDF : mise en page d'impression (page 1 = carte de la vue\n  // actuelle, puis 6 photos par page), enregistree en PDF par le systeme\n  var SIZES = {A4: [210, 297], A3: [297, 420]};\n  var MARGIN = 10;\n  var MM = 96 / 25.4;\n  var dlg = document.getElementById('pdfdlg');\n  var msg = document.getElementById('pdfmsg');\n  var prep = document.getElementById('pdfprep');\n  var go = document.getElementById('pdfgo');\n  var printMap = null;\n\n  function choice(name) {\n    return document.querySelector('input[name=\"' + name + '\"]:checked').value;\n  }\n  function cleanPrint() {\n    if (printMap) { printMap.remove(); printMap = null; }\n    var old = document.getElementById('print');\n    if (old) old.remove();\n    var st = document.getElementById('pagesize');\n    if (st) st.remove();\n  }\n  function resetDialog() {\n    prep.hidden = false; prep.disabled = false; go.hidden = true;\n    msg.textContent = 'Page 1 : la carte (vue actuelle). Pages suivantes : 6 photos par page.';\n  }\n  function page(w, h) {\n    var p = el('section', 'ppage');\n    p.style.width = w + 'mm';\n    p.style.height = h + 'mm';\n    return p;\n  }\n\n  function buildPrint(format, orientation, title) {\n    cleanPrint();\n    var s = SIZES[format];\n    var landscape = orientation === 'landscape';\n    var pw = landscape ? s[1] : s[0];\n    var ph = landscape ? s[0] : s[1];\n    var w = pw - 2 * MARGIN;\n    var h = ph - 2 * MARGIN;\n\n    var st = document.createElement('style');\n    st.id = 'pagesize';\n    st.textContent = '@page { size: ' + format + ' ' + orientation + '; margin: ' + MARGIN + 'mm; }';\n    document.head.appendChild(st);\n\n    var root = el('div');\n    root.id = 'print';\n    document.body.appendChild(root);\n\n    // Page 1 : carte\n    var p1 = page(w, h);\n    p1.appendChild(el('h1', 'ptitle', title));\n    p1.appendChild(el('p', 'psub', photos.length + ' photo(s), ' + located.length +\n      ' g\xe9olocalis\xe9e(s) \xb7 Lambert 93 (EPSG:2154) \xb7 ' + data.generated));\n    var mapDiv = el('div', 'pmap');\n    mapDiv.style.width = Math.floor(w * MM) + 'px';\n    mapDiv.style.height = Math.floor((h - 16) * MM) + 'px';\n    p1.appendChild(mapDiv);\n    root.appendChild(p1);\n\n    // Pages suivantes : 6 photos par page\n    var cols = landscape ? 3 : 2;\n    var rows = landscape ? 2 : 3;\n    for (var start = 0; start < photos.length; start += 6) {\n      var pg = page(w, h);\n      var end = Math.min(start + 6, photos.length);\n      pg.appendChild(el('p', 'psub', title + ' \xb7 photos ' + (start + 1) + ' \xe0 ' + end +\n        ' sur ' + photos.length));\n      var grid = el('div', 'pgrid');\n      grid.style.gridTemplateColumns = 'repeat(' + cols + ', 1fr)';\n      grid.style.gridTemplateRows = 'repeat(' + rows + ', 1fr)';\n      for (var i = start; i < end; i++) {\n        var p = photos[i];\n        var cell = el('div', 'pcell');\n        if (p.img) { var im = el('img'); im.src = p.img; im.alt = p.name; cell.appendChild(im); }\n        else cell.appendChild(el('div', 'noimg', 'Image indisponible'));\n        var cap = el('div', 'pcap');\n        cap.appendChild(el('b', null, (i + 1) + '. ' + p.name));\n        details(p).forEach(function (l, k) { cap.appendChild(el('div', k === 1 ? 'xy' : null, l)); });\n        cell.appendChild(cap);\n        grid.appendChild(cell);\n      }\n      pg.appendChild(grid);\n      root.appendChild(pg);\n    }\n\n    // Carte d'impression : meme fond et meme emprise que la carte affichee\n    return new Promise(function (resolve) {\n      if (!window.L || !map) { resolve(); return; }\n      printMap = L.map(mapDiv, {zoomControl: false, zoomSnap: 0.25});\n      var l = activeLayer;\n      var tiles = L.tileLayer(l.url, {subdomains: l.subdomains, maxZoom: 19,\n        maxNativeZoom: l.maxZoom, attribution: l.attribution}).addTo(printMap);\n      L.control.scale({imperial: false}).addTo(printMap);\n      photos.forEach(function (p, i) {\n        if (p.lat !== null) L.marker([p.lat, p.lng], {icon: pinIcon(i)}).addTo(printMap);\n      });\n      printMap.fitBounds(map.getBounds());\n      var done = false;\n      function finish() { if (!done) { done = true; resolve(); } }\n      tiles.on('load', finish);\n      setTimeout(finish, 8000);\n    });\n  }\n\n  var nameInput = document.getElementById('pdfname');\n  nameInput.value = data.title;\n  nameInput.addEventListener('input', resetDialog);\n  // Changer un choix apres \xab Preparer \xbb oblige a refaire la mise en page\n  Array.prototype.forEach.call(dlg.querySelectorAll('input[type=radio]'),\n    function (r) { r.addEventListener('change', resetDialog); });\n  document.getElementById('pdfbtn').onclick = function () { resetDialog(); dlg.classList.add('open'); };\n  document.getElementById('pdfcancel').onclick = function () {\n    dlg.classList.remove('open'); cleanPrint();\n  };\n  prep.onclick = function () {\n    prep.disabled = true;\n    msg.textContent = 'Pr\xe9paration de la mise en page\u2026';\n    var fmt = choice('fmt');\n    var ori = choice('ori');\n    var title = nameInput.value.trim() || data.title;\n    document.title = title; // nom propose pour le fichier PDF\n    buildPrint(fmt, ori, title).then(function () {\n      var pages = 1 + Math.ceil(photos.length / 6);\n      msg.textContent = 'Pr\xeat : ' + pages + ' page(s) ' + fmt + ' ' +\n        (ori === 'landscape' ? 'paysage' : 'portrait') +\n        '. Dans la fen\xeatre d\\'impression, choisissez \xab Enregistrer en PDF \xbb.';\n      prep.hidden = true;\n      go.hidden = false;\n    });\n  };\n  // Impression lancee par un toucher (exige par Safari sur iPhone)\n  go.onclick = function () { window.print(); };\n  window.addEventListener('afterprint', function () {\n    dlg.classList.remove('open');\n    cleanPrint();\n  });\n\n  // Grille de toutes les photos\n  var grid = document.getElementById('grid');\n  photos.forEach(function (p, i) {\n    var card = el('button', 'card');\n    card.type = 'button';\n    if (p.img) { var im = el('img'); im.src = p.img; im.alt = p.name; im.loading = 'lazy'; card.appendChild(im); }\n    else card.appendChild(el('div', 'noimg', 'Image indisponible'));\n    var info = el('div', 'info');\n    info.appendChild(el('span', 'num', (i + 1) + '.'));\n    info.appendChild(document.createTextNode(p.date + ' ' + p.time));\n    if (p.lat === null) { info.appendChild(el('div', 'nogps', 'sans position')); }\n    card.appendChild(info);\n    card.onclick = function () {\n      if (map && markers[i]) {\n        map.setView([p.lat, p.lng], Math.max(map.getZoom(), 17));\n        markers[i].openPopup();\n        document.getElementById('map').scrollIntoView({behavior: 'smooth', block: 'start'});\n      } else if (p.img) {\n        show(i);\n      }\n    };\n    grid.appendChild(card);\n  });\n})();\n</script>\n</body>\n</html>\n","__LEAFLET_CSS__","https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/leaflet.min.css")
